// selfUpdateFixture is a node's self-update release root seeded with the
// image-baked binary, and a leaf key the offline root delegates to.
type selfUpdateFixture struct {
	t           *testing.T
	layout      selfupdate.Layout
	roots       trust.Keyring
	rootPrivate ed25519.PrivateKey
	leafPrivate ed25519.PrivateKey
	now         time.Time
}

func newSelfUpdateFixture(t *testing.T, roots trust.Keyring, rootPrivate ed25519.PrivateKey, bakedBinary string,
	now time.Time,
) *selfUpdateFixture {
	t.Helper()
	layout := selfupdate.Layout{Root: filepath.Join(t.TempDir(), "release-root"), Owner: os.Getuid()}
	if _, err := selfupdate.Seed(layout, bakedBinary); err != nil {
		t.Fatal(err)
	}
	_, leafPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	return &selfUpdateFixture{t: t, layout: layout, roots: roots, rootPrivate: rootPrivate,
		leafPrivate: leafPrivate, now: now}
}

func (f *selfUpdateFixture) leaf() (string, string) {
	f.t.Helper()
	public := f.leafPrivate.Public().(ed25519.PublicKey)
	keyID, err := trust.KeyID(public)
	if err != nil {
		f.t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(public)
	if err != nil {
		f.t.Fatal(err)
	}
	return keyID, encoded
}

func binaryReceiptFor(data []byte, qualification string) release.BinaryReceipt {
	return release.BinaryReceipt{
		Schema: release.BinarySchema, SourceRevision: strings.Repeat("1", 40), GoVersion: release.DefaultGoVersion,
		GOOS: "linux", GOARCH: "amd64", ELFMachine: "Advanced Micro Devices X86-64", Static: true,
		Bytes: int64(len(data)), SHA256: digest(data), QualificationSHA256: qualification,
	}
}

// updateReceipt signs a binary-update receipt for data under a root
// delegation scoped to environment and cell.
func (f *selfUpdateFixture) updateReceipt(data []byte, environment, cell string) ([]byte, []byte) {
	f.t.Helper()
	keyID, encoded := f.leaf()
	delegation, err := release.SignUpdateDelegation(release.BinaryUpdateDelegation{
		Schema: release.UpdateDelegationSchema, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Environment: environment, Architectures: []string{"amd64"},
		Repository: release.QualificationRepository, Workflow: release.QualificationWorkflow,
		Ref: release.LineageRef, LineageBase: strings.Repeat("9", 40),
	}, f.now.Add(-time.Minute), f.now.Add(time.Hour), f.rootPrivate)
	if err != nil {
		f.t.Fatal(err)
	}
	sum := digest(data)
	qualification := release.Qualification{
		Schema: release.QualificationSchema, Repository: release.QualificationRepository,
		SourceRevision: strings.Repeat("1", 40), SourceTree: strings.Repeat("1", 40), GoVersion: release.DefaultGoVersion,
		GoModSHA256: sum, GoSumSHA256: sum,
		Verification: release.QualificationCheck{Workflow: release.QualificationWorkflow, Job: release.QualificationJob,
			RunID: 10, RunNumber: 5, Conclusion: "success"},
		Artifacts: []release.QualifiedArtifact{
			{Architecture: "amd64", Name: "terrascale-orchestrator-linux-amd64", Bytes: int64(len(data)), SHA256: sum},
			{Architecture: "arm64", Name: "terrascale-orchestrator-linux-arm64", Bytes: int64(len(data)), SHA256: sum},
		},
	}
	qualificationDigest := digest([]byte("qualification"))
	receipt, err := release.SignBinaryUpdateReceipt(binaryReceiptFor(data, qualificationDigest), qualification,
		qualificationDigest, cell, environment, acceptedLineage{}, delegation, f.roots, f.leafPrivate, f.now, 30*time.Minute)
	if err != nil {
		f.t.Fatal(err)
	}
	qualified := release.ProductionQualification{Schema: release.ProductionQualificationSchema,
		Candidate: release.ProductionExpectation{SourceRevision: strings.Repeat("1", 40), ArtifactSHA256: sum,
			QualificationSHA256: qualificationDigest, Cell: cell, Environment: environment,
			Runtime: release.ProductionRuntime, Architecture: "amd64", Role: "orchestrator"}}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		evidence := []byte("test-only " + gate + " evidence")
		qualified.Evidence = append(qualified.Evidence, release.ProductionGateEvidence{Gate: gate,
			SHA256: digest(evidence), Bytes: int64(len(evidence)), CompletedAt: f.now.Add(-time.Second)})
	}
	payload, err := trust.EncodePayload(qualified)
	if err != nil {
		f.t.Fatal(err)
	}
	proof, err := trust.Sign(payload, release.ProductionQualificationScope(qualified.Candidate), f.now, f.now.Add(30*time.Minute), f.rootPrivate)
	if err != nil {
		f.t.Fatal(err)
	}
	receipt, err = release.AttachProductionQualification(receipt, release.ProductionProof{Qualification: envelopeWire(f.t, proof)},
		envelopeWire(f.t, delegation), f.roots, f.leafPrivate,
		release.UpdateExpectation{Environment: environment, Cell: cell, Architecture: "amd64"}, f.now)
	if err != nil {
		f.t.Fatal(err)
	}
	return envelopeWire(f.t, receipt), envelopeWire(f.t, delegation)
}

// perSourceReceipt signs a per-source binary receipt, which is not a
// binary-update receipt.
func (f *selfUpdateFixture) perSourceReceipt(data []byte) ([]byte, []byte) {
	f.t.Helper()
	keyID, encoded := f.leaf()
	delegation, err := trust.SignDelegation(trust.Delegation{
		SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Capabilities: []trust.Capability{{Domain: release.BinaryDomain, DeploymentID: entityid.Derive("build", strings.Repeat("1", 40)),
			Cell: "BUILD", Environment: "production", Role: "artifact", Slots: []string{"linux-amd64"},
			Actions: []string{"sign"}}},
	}, f.now.Add(-time.Minute), f.now.Add(time.Hour), f.rootPrivate)
	if err != nil {
		f.t.Fatal(err)
	}
	receipt, err := release.SignBinaryReceipt(binaryReceiptFor(data, digest([]byte("q"))), "production", delegation,
		f.roots, f.leafPrivate, f.now, 30*time.Minute)
	if err != nil {
		f.t.Fatal(err)
	}
	return envelopeWire(f.t, receipt), envelopeWire(f.t, delegation)
}

// activate stages data the way a rollout does and makes it current.
func (f *selfUpdateFixture) activate(data, receipt, delegation []byte) string {
	f.t.Helper()
	policy := selfupdate.ReceiptPolicy{Roots: f.roots, Environment: "production", Cell: "GRU", Architecture: "amd64"}
	release, err := selfupdate.Stage(f.layout, bytes.NewReader(data), receipt, delegation, policy, f.now)
	if err != nil {
		f.t.Fatal(err)
	}
	if _, err := selfupdate.Activate(f.layout, release, selfUpdateUnit, f.now, selfupdate.MinProofWindow); err != nil {
		f.t.Fatal(err)
	}
	return release
}

// replace rewrites one root-owned, read-only file of release, as a local
// attacker with write access to the release root would.
func (f *selfUpdateFixture) replace(release, name string, data []byte, mode os.FileMode) {
	f.t.Helper()
	path := filepath.Join(f.layout.ReleaseDir(release), name)
	if err := os.Remove(path); err != nil {
		f.t.Fatal(err)
	}
	if err := os.WriteFile(path, data, mode); err != nil {
		f.t.Fatal(err)
	}
}

func (gate Gate) verifyRestartBinary(accepted AcceptedIdentity, roots trust.Keyring) error {
	binary, err := gate.binaryChecker().VerifyAccepted(accepted.Binary)
	if err == nil && binary.SHA256 == accepted.Binary.SHA256 && binary.Bytes == accepted.Binary.Size &&
		binary.Architecture == accepted.Binary.Architecture {
		return nil
	}
	if err == nil {
		err = ErrRunningBinaryMismatch
	}
	if errors.Is(err, ErrRunningBinaryMismatch) && gate.SelfUpdate.Root != "" {
		_, err = gate.binaryChecker().VerifySelfUpdated(gate.SelfUpdate, roots, release.UpdateExpectation{
			Environment: accepted.Environment, Cell: accepted.Cell, Architecture: accepted.Binary.Architecture,
		})
		if err == nil {
			return nil
		}
	}
	return fmt.Errorf("%w: installed executable differs: %v", ErrAdmission, err)
}

func (gate Gate) AdmitRestart(ctx context.Context) (AcceptedIdentity, error) {
	if gate.Instances == nil {
		return AcceptedIdentity{}, fmt.Errorf("%w: authenticated OCI instance observer is absent", ErrAdmission)
	}
	if _, err := gate.checkedNow(); err != nil {
		return AcceptedIdentity{}, err
	}
	accepted, err := gate.AdmitRestartLocal(ctx)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	observed, err := gate.Instances.ObserveInstance(ctx, accepted.InstanceOCID)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("observe accepted OCI instance: %w", err)
	}
	if observed.InstanceOCID != accepted.InstanceOCID || observed.ImageOCID != accepted.ImageOCID ||
		observed.PrimaryVNICOCID != accepted.PrimaryVNICOCID || observed.PrimaryPrivateIP != accepted.PrimaryPrivateIP ||
		!observed.PrimaryVNIC || observed.LifecycleState != "RUNNING" {
		return AcceptedIdentity{}, fmt.Errorf("%w: authenticated OCI physical identity differs from accepted installation", ErrAdmission)
	}
	if _, err := gate.checkedNow(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := ctx.Err(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkAcceptedUnchanged(accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	return accepted, nil
}

func (gate Gate) AdmitRestartLocal(ctx context.Context) (AcceptedIdentity, error) {
	return gate.admitRestartLocal(ctx, gate.verifyRestartBinary)
}

// AdmitIdentityRekeyCompletion admits only the read-only shared-completion probe.
// An owned transition may use its authenticated predecessor without admitting runtime.
func (gate Gate) AdmitIdentityRekeyCompletion(ctx context.Context) (AcceptedIdentity, error) {
	return gate.admitRestartLocal(ctx, func(accepted AcceptedIdentity, roots trust.Keyring) error {
		if err := gate.verifyRestartBinary(accepted, roots); err == nil {
			return nil
		}
		_, err := verifyRecoveryPredecessor("/proc/self/exe", gate.SelfUpdate, roots, accepted)
		return err
	})
}

func (gate Gate) admitRestartLocal(ctx context.Context, verifyBinary func(AcceptedIdentity, trust.Keyring) error) (AcceptedIdentity, error) {
	if gate.Descriptor == nil || gate.Material == nil || gate.Credentials == nil || gate.ObserveIdentity == nil ||
		gate.Markers.directory == "" || !markerDigestRE.MatchString(gate.LoadedControllerConfigSHA256) {
		return AcceptedIdentity{}, fmt.Errorf("%w: required local verifier is absent", ErrAdmission)
	}
	accepted, err := gate.Markers.ReadIdentity()
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read root-owned accepted installation: %w", err)
	}
	inputs, err := gate.acceptedTrustInputs(accepted)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkRestartJournal(accepted, inputs); err != nil {
		return AcceptedIdentity{}, err
	}
	descriptor, err := gate.Descriptor.FetchDescriptor(ctx)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted local slot: %w", err)
	}
	instance, err := gate.Descriptor.FetchInstanceID(ctx)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted local instance ID: %w", err)
	}
	if descriptor.SchemaVersion != 1 || descriptor.Slot != accepted.Slot || instance != accepted.InstanceOCID {
		return AcceptedIdentity{}, fmt.Errorf("%w: IMDS slot or instance differs from accepted installation", ErrAdmission)
	}
	if err := verifyBinary(accepted, inputs.Roots.Historical); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := VerifyAcceptedLocalIdentity(accepted, gate.ObserveIdentity); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify accepted broker/store identity: %w", err)
	}
	pins, err := gate.Material.RestartPins(accepted, inputs.Roots.Historical)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted material generation: %w", err)
	}
	if err := gate.restartConfig(&pins, accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.Material.VerifyRestart(ctx, accepted, pins); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify installed controller material: %w", err)
	}
	if err := gate.Credentials.VerifyLiveCredentials(ctx, pins, accepted); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify live controller credentials: %w", err)
	}
	if err := ctx.Err(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkAcceptedUnchanged(accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := verifyBinary(accepted, inputs.Roots.Historical); err != nil {
		return AcceptedIdentity{}, err
	}
	return accepted, nil
}

func (gate Gate) acceptedTrustInputs(accepted AcceptedIdentity) (TrustInputs, error) {
	if gate.trustStore != nil {
		return gate.trustStore.loadTrustInputs(accepted)
	}
	return LoadTrustInputs(accepted)
}

func (gate Gate) checkRestartJournal(accepted AcceptedIdentity, inputs TrustInputs) error {
	_, err := gate.Markers.verifiedIdentityRekey(accepted, inputs)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	return err
}

func (gate Gate) checkAcceptedUnchanged(accepted AcceptedIdentity) error {
	current, err := gate.Markers.ReadIdentity()
	if err != nil {
		return err
	}
	before, err := EncodeAcceptedIdentity(accepted)
	if err != nil {
		return err
	}
	after, err := EncodeAcceptedIdentity(current)
	if err != nil || !bytes.Equal(before, after) {
		return fmt.Errorf("%w: root-owned accepted installation changed during admission", ErrAdmission)
	}
	inputs, err := gate.acceptedTrustInputs(current)
	if err != nil {
		return err
	}
	return gate.checkRestartJournal(current, inputs)
}

func (gate Gate) observe(ctx context.Context, instanceID string, state bootstrap.SlotState,
	anchor bootstrap.BootstrapAnchor,
) (InstanceObservation, error) {
	observed, err := gate.Instances.ObserveInstance(ctx, instanceID)
	if err != nil {
		return InstanceObservation{}, fmt.Errorf("observe exact OCI instance and primary VNIC: %w", err)
	}
	if state.Result == nil || state.ResultRecord == nil || state.Head.ResultDigest == "" ||
		state.Head.ResultDigest != state.ResultRecord.SHA256 ||
		observed.InstanceOCID != instanceID || state.Result.InstanceOCID != instanceID ||
		observed.ImageOCID != state.Intent.ImageOCID || observed.ImageOCID != state.Result.ImageOCID ||
		observed.CompartmentOCID != state.Intent.CompartmentOCID ||
		observed.CompartmentOCID != state.Result.CompartmentOCID ||
		observed.AvailabilityDomain != state.Intent.AvailabilityDomain ||
		observed.FaultDomain != state.Intent.FaultDomain ||
		observed.Shape != state.Intent.Shape || observed.Shape != state.Result.Shape ||
		observed.SubnetOCID != state.Intent.SubnetOCID ||
		!sameOCIDSet(observed.NSGOCIDs, state.Intent.NetworkSecurityGroupIDs) ||
		state.Intent.DeploymentID != anchor.DeploymentID || state.Intent.Environment != anchor.Environment ||
		state.Intent.Cell != string(anchor.Cell) || state.Intent.OCIRegion != anchor.OCIRegion ||
		state.Result.CreateKey != state.Intent.CreateKey ||
		observed.LifecycleState != "RUNNING" || !observed.PrimaryVNIC ||
		!strings.HasPrefix(observed.PrimaryVNICOCID, "ocid1.vnic.") ||
		!validPrivateIPv4(observed.PrimaryPrivateIP) {
		return InstanceObservation{}, fmt.Errorf("%w: local instance, OCI observation, and signed slot result differ", ErrAdmission)
	}
	observed.Facts = bootstrap.InstanceFacts{
		DeploymentID: anchor.DeploymentID, Environment: anchor.Environment, ClusterID: anchor.ClusterID,
		Cell: anchor.Cell, OCIRegion: anchor.OCIRegion, Role: state.Intent.Role, Slot: state.Intent.Slot,
		InstanceOCID: observed.InstanceOCID, CompartmentOCID: observed.CompartmentOCID,
		ImageOCID: observed.ImageOCID, CreateKey: state.Intent.CreateKey,
		IntentSHA256: state.IntentRecord.SHA256,
		Profile: bootstrap.LaunchProfile{
			Slot: state.Intent.Slot, CompartmentOCID: observed.CompartmentOCID,
			AvailabilityDomain: observed.AvailabilityDomain, FaultDomain: observed.FaultDomain,
			SubnetOCID: observed.SubnetOCID,
			// OCI reports NSG membership without a stable order. The exact set
			// was checked above; keep the signed order for receipt verification.
			NetworkSecurityGroupOCIDs: slices.Clone(state.Intent.NetworkSecurityGroupIDs),
			Shape:                     observed.Shape,
		},
	}
	return observed, nil
}

func sameOCIDSet(left, right []string) bool {
	if len(left) != len(right) {
		return false
	}
	left, right = slices.Clone(left), slices.Clone(right)
	slices.Sort(left)
	slices.Sort(right)
	return slices.Equal(left, right)
}

func expectedMaterials(manifest bootstrap.Manifest, slot string) map[string]string {
	materials := make(map[string]string)
	for _, reference := range slotReferences(manifest, slot) {
		materials[reference.TargetFile] = reference.SHA256
	}
	return materials
}

// slotReferences are the manifest secrets slot's credential directory holds.
func slotReferences(manifest bootstrap.Manifest, slot string) []bootstrap.SecretReference {
	var references []bootstrap.SecretReference
	for _, reference := range manifest.Secrets {
		if (reference.Slot == "" || reference.Slot == slot) &&
			(reference.Purpose != bootstrap.SecretSeedFounder && reference.Purpose != bootstrap.SecretSeedLedgerSigner ||
				slot == manifest.SeedSlot) {
			references = append(references, reference)
		}
	}
	return references
}

func verifyAcceptedBinaryFile(path string, pin identityrekey.BinaryPin) (RunningBinary, error) {
	return verifyBinaryFile(path, release.ImageReceipt{BinarySHA256: pin.SHA256, BinaryBytes: pin.Size, Architecture: pin.Architecture})
}

// verifySelfUpdatedBinary accepts the executable at path when it is the
// current release of the root-owned self-update layout, that release is not
// known bad on this node, and its receipt names it for the expected scope
// and architecture. Restart admission tries it
// only when the executable differs from the accepted binary baseline.
//
// The receipt is checked historically: Stage accepted it as current before
// root kept a byte, so an expired delegation
// never stops a staged release from restarting. Revocation is the known-bad
// list a rollback writes.
func verifySelfUpdatedBinary(path string, layout selfupdate.Layout, roots trust.Keyring,
	expected release.UpdateExpectation,
) (RunningBinary, error) {
	current, err := layout.Current()
	if err != nil {
		return RunningBinary{}, fmt.Errorf("%w: self-update current release: %w", ErrRunningBinaryMismatch, err)
	}
	if current == "" {
		return RunningBinary{}, fmt.Errorf("%w: no self-update current release", ErrRunningBinaryMismatch)
	}
	knownBad, err := layout.KnownBad()
	if err != nil {
		return RunningBinary{}, fmt.Errorf("%w: self-update known-bad releases: %w", ErrRunningBinaryMismatch, err)
	}
	if knownBad[current] {
		return RunningBinary{}, fmt.Errorf("%w: %w", ErrRunningBinaryMismatch, selfupdate.ErrKnownBad)
	}
	receiptWire, delegationWire, err := layout.ReleaseReceipt(current)
	if err != nil {
		return RunningBinary{}, fmt.Errorf("%w: self-update current release: %w", ErrRunningBinaryMismatch, err)
	}
	envelope, err := trust.DecodeEnvelope(receiptWire)
	if err != nil {
		return RunningBinary{}, errors.Join(ErrRunningBinaryMismatch, err)
	}
	var verified release.HistoricalBinary
	switch envelope.Scope.Domain {
	case release.BinaryDomain:
		verified, err = release.VerifyBinaryHistorical(receiptWire, delegationWire, roots, release.BinaryExpectation{Environment: expected.Environment})
	case release.UpdateReceiptDomain:
		verified, err = release.VerifyBinaryUpdateHistorical(receiptWire, delegationWire, roots, expected)
	default:
		return RunningBinary{}, errors.Join(ErrRunningBinaryMismatch, trust.ErrScopeMismatch)
	}
	if err != nil {
		return RunningBinary{}, fmt.Errorf("%w: self-update binary update receipt: %w", ErrRunningBinaryMismatch, err)
	}
	receipt := verified.Receipt()
	if !verified.IsVerified() || receipt.SHA256 != current || receipt.GOARCH != expected.Architecture {
		return RunningBinary{}, fmt.Errorf("%w: binary update receipt names another release", ErrRunningBinaryMismatch)
	}
	return verifyBinaryFile(path, release.ImageReceipt{BinaryBytes: receipt.Bytes, BinarySHA256: receipt.SHA256,
		Architecture: receipt.GOARCH})
}

// verifyRecoveryPredecessor never authorizes a runtime start or target confirmation.
func verifyRecoveryPredecessor(path string, layout selfupdate.Layout, roots trust.Keyring, accepted AcceptedIdentity) (RunningBinary, error) {
	activation, pending, err := layout.Pending()
	if errors.Is(err, selfupdate.ErrUnreadableActivation) {
		activation, err = layout.RecoveryActivation()
		pending = err == nil
	}
	if err != nil {
		return RunningBinary{}, errors.Join(ErrRunningBinaryMismatch, err)
	}
	if !pending {
		intents, err := layout.PendingRestores()
		if err != nil {
			return RunningBinary{}, errors.Join(ErrRunningBinaryMismatch, err)
		}
		for _, intent := range intents {
			if intent.Unit == selfupdate.ControllerUnit {
				return verifyRecoveryRelease(path, layout, intent.Target, roots, accepted)
			}
		}
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	if activation.Unit != selfupdate.ControllerUnit {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	current, err := layout.Current()
	if err != nil || current != activation.Target {
		return RunningBinary{}, errors.Join(ErrRunningBinaryMismatch, err)
	}
	bad, err := layout.KnownBad()
	if err != nil || bad[activation.Previous] {
		return RunningBinary{}, errors.Join(ErrRunningBinaryMismatch, err)
	}
	return verifyRecoveryRelease(path, layout, activation.Previous, roots, accepted)
}

func verifyRecoveryRelease(path string, layout selfupdate.Layout, digest string, roots trust.Keyring, accepted AcceptedIdentity) (RunningBinary, error) {
	if err := layout.VerifyRelease(digest); err != nil {
		return RunningBinary{}, err
	}
	if digest == accepted.Binary.SHA256 {
		return verifyAcceptedBinaryFile(path, accepted.Binary)
	}
	receiptWire, delegationWire, err := layout.ReleaseReceipt(digest)
	if err != nil {
		return RunningBinary{}, err
	}
	envelope, err := trust.DecodeEnvelope(receiptWire)
	if err != nil {
		return RunningBinary{}, err
	}
	var verified release.HistoricalBinary
	switch envelope.Scope.Domain {
	case release.BinaryDomain:
		verified, err = release.VerifyBinaryHistorical(receiptWire, delegationWire, roots, release.BinaryExpectation{Environment: accepted.Environment})
	case release.UpdateReceiptDomain:
		verified, err = release.VerifyBinaryUpdateHistorical(receiptWire, delegationWire, roots, release.UpdateExpectation{Environment: accepted.Environment, Cell: accepted.Cell, Architecture: accepted.Binary.Architecture})
	default:
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	if err != nil {
		return RunningBinary{}, err
	}
	receipt := verified.Receipt()
	if !verified.IsVerified() || receipt.SHA256 != digest || receipt.GOARCH != accepted.Binary.Architecture {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	return verifyBinaryFile(path, release.ImageReceipt{BinaryBytes: receipt.Bytes, BinarySHA256: receipt.SHA256, Architecture: receipt.GOARCH})
}

func verifyBinaryFile(path string, receipt release.ImageReceipt) (RunningBinary, error) {
	file, err := os.Open(path)
	if err != nil {
		return RunningBinary{}, fmt.Errorf("open running binary: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > release.MaxArtifactBytes ||
		info.Size() != receipt.BinaryBytes {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	parsed, err := elf.NewFile(file)
	if err != nil || parsed.Class != elf.ELFCLASS64 || parsed.Data != elf.ELFDATA2LSB {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	architecture := ""
	switch parsed.Machine {
	case elf.EM_X86_64:
		architecture = "amd64"
	case elf.EM_AARCH64:
		architecture = "arm64"
	default:
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	if architecture != receipt.Architecture {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	hash := sha256.New()
	read := io.NewSectionReader(file, 0, info.Size())
	count, err := io.Copy(hash, read)
	if err != nil || count != info.Size() {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	digest := hex.EncodeToString(hash.Sum(nil))
	if digest != receipt.BinarySHA256 {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	return RunningBinary{SHA256: digest, Bytes: count, Architecture: architecture}, nil
}

