func (store bakedStore) load() (BakedInputs, error) {
	dir, err := store.openDirectory(store.directory)
	if err != nil {
		return BakedInputs{}, fmt.Errorf("open baked bootstrap directory: %w", err)
	}
	defer unix.Close(dir)
	identityWire, err := store.readFile(dir, identityFilename, maxIdentity)
	if err != nil {
		return BakedInputs{}, fmt.Errorf("read baked identity: %w", err)
	}
	identity, err := parseBakedIdentity(identityWire)
	if err != nil {
		return BakedInputs{}, err
	}
	anchorWire, err := store.readFile(dir, anchorFilename, bootstrap.MaxBootstrapAnchorBytes)
	if err != nil {
		return BakedInputs{}, fmt.Errorf("read baked anchor: %w", err)
	}
	if _, err := trust.DecodeEnvelope(anchorWire); err != nil {
		return BakedInputs{}, fmt.Errorf("decode baked anchor: %w", err)
	}
	genesis, err := store.loadRoots()
	if err != nil {
		return BakedInputs{}, err
	}
	chain, err := readRootChain(store.chainFile)
	if err != nil {
		return BakedInputs{}, err
	}
	verified, err := trust.VerifyRootChain(genesis, identity.ChainIdentity(), chain)
	if err != nil {
		return BakedInputs{}, fmt.Errorf("verify adopted root chain: %w", err)
	}
	return BakedInputs{Identity: identity, Genesis: genesis, Chain: chain, Roots: verified.Historical,
		AnchorWire: anchorWire}, nil
}

// readRootChain reads the adopted chain; a controller that never adopted
// one has no file. The chain verifies from the baked genesis, so the file
// needs no ownership pin, but a damaged file fails closed rather than
// falling back to the genesis roots.
func readRootChain(path string) (trust.RootChain, error) {
	if path == "" {
		return trust.RootChain{Version: 1}, nil
	}
	// O_NONBLOCK keeps a FIFO from hanging the open; it is refused below.
	file, err := os.OpenFile(path, os.O_RDONLY|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if errors.Is(err, os.ErrNotExist) {
		return trust.RootChain{Version: 1}, nil
	}
	if err != nil {
		return trust.RootChain{}, fmt.Errorf("open adopted root chain: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return trust.RootChain{}, fmt.Errorf("stat adopted root chain %s: %w", path, err)
	}
	if !info.Mode().IsRegular() {
		return trust.RootChain{}, fmt.Errorf("adopted root chain %s is not a regular file", path)
	}
	wire, err := io.ReadAll(io.LimitReader(file, trust.MaxRootChainBytes+1))
	if err != nil {
		return trust.RootChain{}, fmt.Errorf("read adopted root chain: %w", err)
	}
	return trust.DecodeRootChain(wire)
}

// parseBakedIdentity accepts only the canonical encoding, so the installed
// bytes and every digest over them stay unambiguous.
func parseBakedIdentity(wire []byte) (BakedIdentity, error) {
	var identity BakedIdentity
	if err := protocol.DecodeStrict(wire, &identity, maxIdentity); err != nil ||
		identity.SchemaVersion != 1 || !entityid.Valid(identity.DeploymentID) ||
		identity.Environment != "production" && identity.Environment != "canary" {
		return BakedIdentity{}, ErrBakedInputs
	}
	if _, err := identity.Cell.OCIRegion(); err != nil {
		return BakedIdentity{}, ErrBakedInputs
	}
	canonical, err := protocol.EncodeJSON(identity)
	if err != nil || !bytes.Equal(wire, canonical) {
		return BakedIdentity{}, ErrBakedInputs
	}
	return identity, nil
}

// loadRoots reads the image's trust roots, the only bootstrap authority the
// image itself carries.
func (store bakedStore) loadRoots() (trust.Keyring, error) {
	rootsDir, err := store.openDirectory(filepath.Join(store.directory, "trust-roots"))
	if err != nil {
		return nil, fmt.Errorf("open baked trust roots: %w", err)
	}
	file := os.NewFile(uintptr(rootsDir), "trust-roots")
	defer file.Close()
	names, err := file.Readdirnames(-1)
	if err != nil {
		return nil, fmt.Errorf("read baked root entries: %w", err)
	}
	if len(names) == 0 || len(names) > MaxRootFiles {
		return nil, ErrBakedInputs
	}
	sort.Strings(names)
	keys := make([]ed25519.PublicKey, 0, len(names))
	total := 0
	for _, name := range names {
		if !rootFilenameRE.MatchString(name) || name == "000.pem" {
			return nil, ErrBakedInputs
		}
		wire, err := store.readFile(rootsDir, name, MaxRootBytes)
		if err != nil {
			return nil, fmt.Errorf("read baked root %s: %w", name, err)
		}
		total += len(wire)
		if total > MaxRootsTotal {
			return nil, ErrBakedInputs
		}
		block, rest := pem.Decode(wire)
		if block == nil || block.Type != "PUBLIC KEY" || len(block.Headers) != 0 || len(bytes.TrimSpace(rest)) != 0 {
			return nil, ErrBakedInputs
		}
		publicKey, err := x509.ParsePKIXPublicKey(block.Bytes)
		key, ok := publicKey.(ed25519.PublicKey)
		if err != nil || !ok || len(key) != ed25519.PublicKeySize {
			return nil, ErrBakedInputs
		}
		keys = append(keys, key)
	}
	roots, err := trust.ParseKeyring(keys...)
	if err != nil {
		return nil, fmt.Errorf("assemble unambiguous root key IDs: %w", err)
	}
	return roots, nil
}

func (store bakedStore) openDirectory(path string) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrBakedInputs
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for _, component := range strings.Split(strings.TrimPrefix(path, "/"), "/") {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrBakedInputs
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			!store.allowUnsafeAncestors && (stat.Uid != 0 || stat.Gid != 0 || stat.Mode&0o777 != 0o755) {
			unix.Close(fd)
			return -1, ErrBakedInputs
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil ||
		stat.Uid != store.ownerUID || stat.Gid != store.ownerGID || stat.Mode&0o777 != 0o755 {
		unix.Close(fd)
		return -1, ErrBakedInputs
	}
	return fd, nil
}

func (store bakedStore) readFile(dir int, name string, maximum int64) ([]byte, error) {
	if strings.Contains(name, "/") || name == "" || maximum <= 0 {
		return nil, ErrBakedInputs
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || stat.Gid != store.ownerGID ||
		stat.Mode&0o7777 != 0o444 || stat.Nlink != 1 || stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrBakedInputs
	}
	wire, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(wire) == 0 || int64(len(wire)) > maximum {
		return nil, ErrBakedInputs
	}
	return wire, nil
}

func VerifyControllerConfigInstall(ctx context.Context, baked BakedInputs, wire []byte,
	descriptor DescriptorSource, instances InstanceObserver, now time.Time,
) (bootstrap.Manifest, InstanceObservation, error) {
	if len(wire) == 0 || len(wire) > MaxControllerManifestMetadataBytes ||
		descriptor == nil || instances == nil || now.IsZero() || now.Location() != time.UTC {
		return bootstrap.Manifest{}, InstanceObservation{}, ErrControllerConfigInstall
	}
	anchorEnvelope, err := trust.DecodeEnvelope(baked.AnchorWire)
	if err != nil {
		return bootstrap.Manifest{}, InstanceObservation{}, err
	}
	anchor, err := bootstrap.VerifyBootstrapAnchor(anchorEnvelope, baked.Roots,
		baked.Identity.AnchorExpectation(), now, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil {
		return bootstrap.Manifest{}, InstanceObservation{}, fmt.Errorf("verify baked controller anchor: %w", err)
	}
	desc, err := descriptor.FetchDescriptor(ctx)
	if err != nil || desc.SchemaVersion != 1 || !slices.Contains(anchor.Anchor().ControllerSlots, desc.Slot) {
		return bootstrap.Manifest{}, InstanceObservation{}, ErrControllerConfigInstall
	}
	instanceID, err := descriptor.FetchInstanceID(ctx)
	if err != nil || !instanceIDRE.MatchString(instanceID) {
		return bootstrap.Manifest{}, InstanceObservation{}, ErrControllerConfigInstall
	}
	manifestEnvelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return bootstrap.Manifest{}, InstanceObservation{}, err
	}
	unsigned, err := bootstrap.ManifestPayload(manifestEnvelope.Payload)
	if err != nil || unsigned.Slot != desc.Slot {
		return bootstrap.Manifest{}, InstanceObservation{}, ErrControllerConfigInstall
	}
	expected, err := anchor.ManifestExpectation(desc.Slot, unsigned.ImageOCID)
	if err != nil {
		return bootstrap.Manifest{}, InstanceObservation{}, err
	}
	verified, err := bootstrap.VerifyManifest(manifestEnvelope, baked.Roots, expected, now,
		bootstrap.ManifestTrustPolicy())
	if err != nil {
		return bootstrap.Manifest{}, InstanceObservation{}, fmt.Errorf("verify root-signed controller manifest: %w", err)
	}
	manifest := verified.Manifest()
	_, err = release.VerifyImageCurrent(manifest.ReleaseImageReceiptWire, manifest.ReleaseDelegationWire,
		baked.Roots, release.ImageExpectation{Environment: manifest.Environment,
			LogicalRegion: string(manifest.Cell), OCIImageOCID: manifest.ImageOCID,
			Architecture: strings.TrimPrefix(manifest.ImageArchitecture, "linux-")}, now)
	if err != nil {
		return bootstrap.Manifest{}, InstanceObservation{}, fmt.Errorf("%w: release image proof: %v", ErrControllerConfigInstall, err)
	}
	observed, err := instances.ObserveInstance(ctx, instanceID)
	if err != nil {
		return bootstrap.Manifest{}, InstanceObservation{}, fmt.Errorf("observe local OCI instance: %w", err)
	}
	profile, ok := verified.Profile(desc.Slot)
	if !ok || observed.InstanceOCID != instanceID || observed.ImageOCID != manifest.ImageOCID ||
		observed.CompartmentOCID != profile.CompartmentOCID ||
		observed.AvailabilityDomain != profile.AvailabilityDomain || observed.FaultDomain != profile.FaultDomain ||
		observed.Shape != profile.Shape || observed.SubnetOCID != profile.SubnetOCID ||
		!sameOCIDSet(observed.NSGOCIDs, profile.NetworkSecurityGroupOCIDs) ||
		observed.LifecycleState != "RUNNING" || !observed.PrimaryVNIC ||
		!validPrivateIPv4(observed.PrimaryPrivateIP) {
		return bootstrap.Manifest{}, InstanceObservation{}, ErrControllerConfigInstall
	}
	return manifest, observed, nil
}

func founderLaunchSDKRequest(request bootstrap.FounderPeerLaunchRequest, material LaunchMaterial) (core.LaunchInstanceRequest, error) {
	row := request.Row
	manifestHash := sha256.Sum256(request.ManifestWire)
	manifestEnvelope, manifestErr := trust.DecodeEnvelope(request.ManifestWire)
	var manifest bootstrap.Manifest
	derived, isDerived := request.StartupAuthority.(bootstrap.DerivedStartupAuthority)
	if isDerived {
		if !derived.IsVerified() || derived.Digest() != request.ManifestSHA256 || !bytes.Equal(derived.Wire(), request.ManifestWire) {
			return core.LaunchInstanceRequest{}, ErrFounderOCI
		}
		manifest, manifestErr = derived.Manifest(), nil
	} else if manifestErr == nil {
		manifest, manifestErr = bootstrap.ManifestPayload(manifestEnvelope.Payload)
	}
	vpus, ok := row.BootVolumeTier.VPUsPerGB()
	if !ok || vpus != 10 || row.Slot != request.Slot || row.WholeOCPUs == 0 ||
		row.MemoryInGB == 0 || row.BootVolumeGB < founderMinBootVolumeGB ||
		row.BootVolumeGB > founderMaxBootVolumeGB || request.RetryToken == "" ||
		row.WholeOCPUs > 1<<24 || row.MemoryInGB > 1<<24 ||
		len(request.ManifestWire) == 0 || len(request.ManifestWire) > bootstrap.MaxManifestBytes || !isDerived && len(request.ManifestWire) > MaxControllerManifestMetadataBytes ||
		hex.EncodeToString(manifestHash[:]) != request.ManifestSHA256 || manifestErr != nil ||
		manifest.Slot != request.Slot || manifest.DeploymentID != request.DeploymentID ||
		manifest.Cell != request.Cell || manifest.Environment != request.Environment ||
		manifest.ImageOCID != row.ImageOCID ||
		len(material.Identity) == 0 || len(material.Anchor) == 0 || len(material.HostEnrollment) == 0 ||
		len(material.OperatorSSHKey) == 0 || len(material.ManagedHostImageReceipt) == 0 ||
		len(material.ManagedHostImageDelegation) == 0 {
		return core.LaunchInstanceRequest{}, ErrFounderOCI
	}
	descriptor, err := protocol.EncodeJSON(Descriptor{SchemaVersion: 1, Slot: request.Slot})
	if err != nil {
		return core.LaunchInstanceRequest{}, err
	}
	// The deployment ID stays in the manifest launch metadata, not the name.
	name, err := naming.RegionCell(string(request.Cell)).ControllerSlot(request.Slot)
	if err != nil {
		return core.LaunchInstanceRequest{}, ErrFounderOCI
	}
	metadata := material.ControllerMetadata()
	metadata["terrascale-bootstrap"] = string(descriptor)
	if !isDerived {
		metadata["terrascale-controller-manifest-v1"] = string(request.ManifestWire)
	}
	return core.LaunchInstanceRequest{
		OpcRetryToken: new(request.RetryToken), RequestMetadata: noFounderSDKRetry(),
		LaunchInstanceDetails: core.LaunchInstanceDetails{
			AvailabilityDomain: new(row.AvailabilityDomain), CompartmentId: new(row.CompartmentOCID),
			FaultDomain: new(row.FaultDomain), Shape: new(row.Shape),
			DisplayName: new(name),
			Metadata:    metadata,
			ShapeConfig: &core.LaunchInstanceShapeConfigDetails{
				Ocpus: new(float32(row.WholeOCPUs)), MemoryInGBs: new(float32(row.MemoryInGB)),
			},
			SourceDetails: core.InstanceSourceViaImageDetails{
				ImageId: new(row.ImageOCID), BootVolumeSizeInGBs: new(int64(row.BootVolumeGB)),
				BootVolumeVpusPerGB: new(int64(vpus)),
			},
			CreateVnicDetails: &core.CreateVnicDetails{
				SubnetId: new(row.SubnetOCID), NsgIds: slices.Clone(row.NetworkSecurityGroupOCIDs),
				PrivateIp: new(row.PrivateIP), AssignPublicIp: new(false),
			},
		},
	}, nil
}

